UPDATE holdings SET instrument_id = (SELECT id FROM instruments WHERE price_source = 'MANUAL' AND source_ref = 'EUR') WHERE id = '99999999-9999-9999-9999-999999999924' AND NOT EXISTS ( SELECT 1 FROM holdings WHERE account_id = '99999999-9999-9999-9999-999999999903' AND instrument_id = (SELECT id FROM instruments WHERE price_source = 'MANUAL' AND source_ref = 'EUR'));
DELETE FROM holdings WHERE id = '99999999-9999-9999-9999-999999999924' AND instrument_id = '99999999-9999-9999-9999-999999999914';
INSERT INTO holdings (id, account_id, instrument_id, quantity, average_cost, updated_at) SELECT '99999999-9999-9999-9999-999999999925', '99999999-9999-9999-9999-999999999904', id, 500, 1, now() FROM instruments WHERE price_source = 'MANUAL' AND source_ref = 'EUR';
